B64
tar -xzf "$PAY/p.tgz" -C "$PAY"; rm -f "$PAY/p.tgz"
(cd "$PAY" && md5sum -c --quiet MD5SUMS) || { echo "$T: embedded files damaged" >&2; exit 1; }
f=sub-smegov-v19pre; want=121
dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$PAY/media/$f.mp4")
python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<2 else 1)" || { echo "$T: $f length $dur, expected ~$want s" >&2; exit 1; }
wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$PAY/media/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "$T: $f size $wh" >&2; exit 1; }
head -1 "$PAY/media/$f.th.vtt" | grep -q '^WEBVTT' || { echo "$T: $f vtt header" >&2; exit 1; }
mkdir -p "$M/media" "$M/img"
# skip the mp4 once video_offload has moved it to a video repo (the page then links /video-N/...)
grep -q "/video-[0-9]*/commerce/2569/media/$f.mp4" "$M/sub-smegov.html" || { cmp -s "$PAY/media/$f.mp4" "$M/media/$f.mp4" || cp -f "$PAY/media/$f.mp4" "$M/media/$f.mp4"; }
cmp -s "$PAY/media/$f.th.vtt" "$M/media/$f.th.vtt" || cp -f "$PAY/media/$f.th.vtt" "$M/media/$f.th.vtt"
cmp -s "$PAY/media/poster-sub-smegov-19pre.jpg" "$M/img/poster-sub-smegov-19pre.jpg" || cp -f "$PAY/media/poster-sub-smegov-19pre.jpg" "$M/img/poster-sub-smegov-19pre.jpg"
python3 "$PAY/apply_v.py" "$M" "$HUB" "$PAY/payload_218.json"
NEWP="v-smegov-19-pre.html"
need=0; test -f "$M/s/$NEWP" || need=1
grep -q '"19":"s/v-smegov-19-pre.html' "$M/sub-smegov.html" || need=1
if [ $need = 1 ]; then
  for g in "$M"/s/v-*.html; do b=$(basename "$g"); case " $NEWP " in *" $b "*) ;; *) cp -p "$g" "$KEEP/$b";; esac; done
  CARD_BIG=1 python3 "$BUILD/video_share.py" "$M" https://parliamentx.com/commerce/2569 2569
  for b in $NEWP; do test -f "$M/s/$b" || { echo "$T: share page s/$b missing" >&2; exit 1; }; python3 "$BUILD/mobile.py" "$M/s/$b" >/dev/null; done
  python3 "$BUILD/no_video_dl.py" "$M/s"
  for g in "$KEEP"/*.html; do cmp -s "$g" "$M/s/$(basename "$g")" || cp -f "$g" "$M/s/$(basename "$g")"; done
fi
python3 "$BUILD/no_video_dl.py" --check "$M"
MP="$BUILD/meeting_pages.py"; test -s "$MP" || MP="$PAY/meeting_pages.py"
python3 "$MP" "$M" >/dev/null
python3 - "$M" <<'PY'
import json, sys
M = sys.argv[1]; dec = json.JSONDecoder()
def val(p, c):
    for l in open(p, encoding="utf-8").read().split("\n"):
        if l.startswith(c): return dec.raw_decode(l[len(c):])[0]
for src in ({m["n"]: m for m in val(f"{M}/sub-smegov.html", "const DATA=")}, {m["n"]: m for m in json.load(open(f"{M}/sub-smegov.json", encoding="utf-8"))}):
    ks = lambda n: sorted(v["kind"] + ":" + v["ck"] for v in src[n]["media"]["videos"])
    assert ks(19) == ["pre:smegov-19p"] and ks(18) == ["pre:smegov-18p"] and ks(17) == ["pre:smegov-17p"], "218: smegov media"
    assert src[19]["media"]["video"]["dur"] == "2:01" and src[19].get("upcoming"), "218: smegov 19"
g = open(f"{M}/sub-smegov.html", encoding="utf-8").read()
assert val(f"{M}/sub-smegov.html", "const CAPS=").get("smegov-19p", "").startswith("WEBVTT"), "218: CAPS"
assert '"19":"s/v-smegov-19-pre.html' in g and '"18":"s/v-smegov-18-pre.html' in g, "218: VSHARE"
for b in ("v-smegov-19-pre.html", "v-smegov-18-pre.html"):
    h = open(f"{M}/s/{b}", encoding="utf-8").read()
    assert '<style data-mb>' in h and 'id="novdl-css"' in h, f"218: s/{b} phone/no-download layer missing"
assert "poster-sub-smegov-19pre.jpg" in open(f"{M}/m/smegov-19.html", encoding="utf-8").read(), "218: meeting page shows the video"
print("218_commerce_smegov19_pre OK")
PY
